From 0afb03d9c3fc13df43e04baedfd85245d5eef8e0 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 20:53:32 +0100
Subject: [PATCH] foldermodel: place a replaced file where it was dropped

Dropping a file over one with the same name kept the old icon's spot,
because the overwritten item is never inserted again and so the drop
position was never applied. Move the existing item there right away.

BUG: 517579
---
 containments/desktop/plugins/folder/foldermodel.cpp | 6 ++++++
 1 file changed, 6 insertions(+)

diff --git a/containments/desktop/plugins/folder/foldermodel.cpp b/containments/desktop/plugins/folder/foldermodel.cpp
index 678bae687c..41256c4e30 100644
--- a/containments/desktop/plugins/folder/foldermodel.cpp
+++ b/containments/desktop/plugins/folder/foldermodel.cpp
@@ -1445,6 +1445,12 @@ void FolderModel::drop(QQuickItem *target, QObject *dropEvent, int row, bool sho
             if ((dropTargetUrl.path() + QStringLiteral("/") + targetUrl.fileName()) != targetUrl.path()) {
                 return;
             }
+            // An overwritten item is not inserted again, so move it right away
+            const KFileItem existingItem = m_dirModel->dirLister()->findByName(targetUrl.fileName());
+            if (!existingItem.isNull() && indexForUrl(existingItem.url()) != -1) {
+                Q_EMIT move(dropPos.x(), dropPos.y(), {existingItem.url()});
+                return;
+            }
             m_dropTargetPositions.insert(targetUrl.fileName(), dropPos);
             m_dropTargetPositionsCleanup->start();

-- 
